css:
/* Reset box-sizing for all elements */
* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* Make sure the entire page takes full height */
html, body {
  height: 100%;
}

/* Center everything in the viewport */
body {
  display: flex;
  justify-content: center;
  align-items: center;
  background: linear-gradient(to top, #116bb2 0%, #68d0e0 100%);
  font-family: sans-serif;
}

/* Main container holding the text */
main {
  display: flex;
  justify-content: center;
  align-items: center;
  width: 480px;
  height: 480px;
  background: #fff;
  border-radius: 12px; /* Slight rounding for a softer look */
  box-shadow: 0 10px 20px rgba(0, 0, 0, 0.15); /* Adds depth */
}

/* Styled text with background clipping */
.clip-text {
  font-size: 7rem;
  font-weight: 700;
  text-align: center;
  color: #68d0e0; /* Fallback color */
}

/* Apply background image inside text */
@supports (background-clip: text) or (-webkit-background-clip: text) {
  .clip-text {
    color: transparent;
    background-clip: text;
    -webkit-background-clip: text;
    background-image: url(https://media.giphy.com/media/xULW8Fw2ZhznUptrYA/giphy.gif);
    background-size: cover;
    background-position: center;
  }
}

/* Optional heading styles */
h1 {
  color: #fff;
  text-align: center;
}

/* Styling for code blocks */
h1 pre span {
  background-color: rgba(0, 0, 0, 0.15);
  padding: 0.3rem;
  border-radius: 6px;
}

/* Links section */
.links {
  text-align: center;
  margin-top: 1rem;
}

.links a {
  color: #fff;
  font-size: 0.8rem;
  text-decoration: none;
  transition: 0.3s ease-in-out;
}

.links a:hover {
  text-decoration: underline;
}
